import csv
with open('ae_ci_age_gender.csv', newline='') as f:
    rdr = csv.reader(f)
    header = next(rdr)
    rows = [r for r in rdr if r]
print('header:', header)
print('nrows:', len(rows))
def col(name):
    for i,h in enumerate(header):
        if name.lower() in h.lower():
            return i
    return None
iy = col('year')
print('year_col_idx:', iy)
if iy is None:
    for r in rows[:40]:
        print(r)
else:
    years = sorted(set(r[iy].strip() for r in rows))
    print('years:', years)
    for y in ('2021','2022','2023','2024'):
        sub = [r for r in rows if r[iy].strip()==y]
        print('==', y, 'n=', len(sub))
        for r in sub[:25]:
            print(r)
